"use client";

import { motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { cn } from "@/lib/utils";

import {
  COHORTS,
  COHORT_SHADES,
  COHORT_SHADE_LABELS,
  type Cohort,
  type CohortCell,
  type CohortSegment,
  cohortPercent,
  retentionAt,
} from "../lib/cohort-retention-data";
import { formatOnePlace, formatWhole } from "../lib/format";
import { ROLL_ONE_PLACE } from "../lib/roll-formats";
import { BlockFrame } from "../parts/block-frame";
import { RetentionCurves } from "./cohort-retention/retention-curves";
import { RetentionGrid } from "./cohort-retention/retention-grid";

type View = "heatmap" | "curves";

const SEGMENTS: { value: CohortSegment; label: string; noun: string }[] = [
  { value: "all", label: "All", noun: "all clinics" },
  { value: "selfServe", label: "Self-serve", noun: "self-serve clinics" },
  { value: "salesLed", label: "Sales-led", noun: "sales-led clinics" },
];

const VIEWS: { value: View; label: string }[] = [
  { value: "heatmap", label: "Heatmap" },
  { value: "curves", label: "Curves" },
];

const HEADLINE_MONTHS = [1, 3, 6];

/** The cohort that kept the largest share of its clinics in a given month. */
function bestCohort(cohorts: Cohort[], month: number): Cohort | undefined {
  return cohorts
    .filter((cohort) => cohort.retained[month] !== undefined)
    .reduce<Cohort | undefined>(
      (best, cohort) => (best && cohortPercent(best, month) >= cohortPercent(cohort, month) ? best : cohort),
      undefined,
    );
}

/**
 * Shows how many clinics keep booking after they sign up, one row per signup
 * month. The same figures read as a shaded grid or as curves, and one cell
 * cursor follows the reader between the two views.
 */
export function CohortRetention({ className }: { className?: string }) {
  const [segment, setSegment] = useState<CohortSegment>("all");
  const [view, setView] = useState<View>("heatmap");
  const [cursor, setCursor] = useState<CohortCell>({ row: 0, col: 1 });
  const [active, setActive] = useState(false);
  const [hover, setHover] = useState<CohortCell | null>(null);
  const reduceMotion = useReducedMotion();
  const titleId = useId();

  const cohorts = COHORTS[segment];
  const noun = SEGMENTS.find((item) => item.value === segment)?.noun ?? "clinics";
  const inspected = hover ?? (active ? cursor : null);

  const best = bestCohort(cohorts, 3);
  // One short result that the three figures above do not already state.
  const summary = best
    ? `${best.label} signups hold best: ${formatOnePlace(cohortPercent(best, 3))}% still book after three months.`
    : "";

  const describe = (cell: CohortCell) => {
    const cohort = cohorts[cell.row];
    if (!cohort) return "";
    if (cell.col === 0) return `${cohort.label} signups: ${formatWhole(cohort.size)} clinics.`;
    const count = cohort.retained[cell.col] ?? 0;
    return `${cohort.label} signups, month ${cell.col}: ${formatWhole(count)} of ${formatWhole(cohort.size)} clinics still booking, ${formatOnePlace(cohortPercent(cohort, cell.col))}%.`;
  };

  const details = (cell: CohortCell) => {
    const cohort = cohorts[cell.row];
    const count = cohort?.retained[cell.col] ?? 0;
    return {
      title: `${cohort?.label ?? ""} signups`,
      rows: [
        { label: "Month", value: String(cell.col) },
        { label: "Still booking", value: `${formatOnePlace(cohort ? cohortPercent(cohort, cell.col) : 0)}%`, marker: "bg-chart-1" },
        { label: "Clinics", value: `${formatWhole(count)} of ${formatWhole(cohort?.size ?? 0)}` },
      ],
    };
  };

  const viewProps = {
    label: `Retention of ${noun} by signup month`,
    cohorts,
    cursor,
    inspected,
    details,
    onCursor: setCursor,
    onActive: setActive,
    onHover: setHover,
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Clinic retention
          </h2>
          <p className="truncate text-sm text-muted-foreground">Signups, Feb to Oct 2026</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <SegmentedControl aria-label="Segment" options={SEGMENTS} value={segment} onValueChange={setSegment} />
          <SegmentedControl aria-label="View" options={VIEWS} value={view} onValueChange={setView} />
        </div>
      </header>

      <dl className="grid grid-cols-1 gap-px border-b border-border bg-border @md:grid-cols-3">
        {HEADLINE_MONTHS.map((month) => {
          const figure = retentionAt(cohorts, month);
          return (
            <div key={month} className="flex flex-col gap-1 bg-card px-5 py-4">
              <dt className="text-sm whitespace-nowrap text-muted-foreground">After {month === 1 ? "1 month" : `${month} months`}</dt>
              <dd className="text-2xl font-semibold tracking-tight tabular-nums">
                <NumberTicker value={figure.percent} format={ROLL_ONE_PLACE} />%
              </dd>
              <dd className="text-xs tabular-nums text-muted-foreground">
                {formatWhole(figure.retained)} of {formatWhole(figure.size)}
              </dd>
            </div>
          );
        })}
      </dl>

      <div className="flex flex-col gap-4 p-5">
        <p className="min-h-10 text-sm text-muted-foreground @xl:min-h-5">{summary}</p>
        <p aria-live="polite" className="sr-only">
          {inspected ? describe(inspected) : ""}
        </p>
        {/* Both views share one grid cell, so the block keeps the height of the taller one. */}
        <div className="grid">
          {VIEWS.map((item) => {
            const shown = item.value === view;
            return (
              <motion.div
                key={item.value}
                inert={!shown}
                aria-hidden={!shown}
                initial={false}
                animate={{ opacity: shown ? 1 : 0 }}
                transition={{ duration: reduceMotion ? 0 : 0.18 }}
                className={cn("col-start-1 row-start-1 flex min-w-0 flex-col gap-4", shown ? undefined : "invisible")}
              >
                {item.value === "heatmap" ? (
                  <>
                    <RetentionGrid {...viewProps} />
                    <ul aria-label="Shade key, percent still booking" className="flex gap-3 text-xs whitespace-nowrap text-muted-foreground tabular-nums">
                      {COHORT_SHADE_LABELS.map((text, step) => (
                        <li key={text} className="flex items-center gap-1.5">
                          <span aria-hidden="true" className={cn("size-3 rounded-sm border border-border", COHORT_SHADES[step])} />
                          {text}
                        </li>
                      ))}
                    </ul>
                  </>
                ) : (
                  <RetentionCurves {...viewProps} />
                )}
              </motion.div>
            );
          })}
        </div>
      </div>
    </BlockFrame>
  );
}

import { seededRandom } from "./plot";

/** Which clinics a retention view counts: everyone, or one way of signing up. */
export type CohortSegment = "all" | "selfServe" | "salesLed";

/** The clinics that signed up in one month, and how many of them still book in each later month. */
export interface Cohort {
  /** The signup month, such as Feb 2026. */
  label: string;
  size: number;
  /** Clinics still booking in each month since signup. Month 0 is the whole cohort. */
  retained: number[];
}

/** One cell of the retention triangle: a cohort row and a month since signup. */
export interface CohortCell {
  row: number;
  col: number;
}

/** How many signup months the sample holds. The oldest cohort has this many months of history. */
export const COHORT_MONTHS = 9;

const MONTH = new Intl.DateTimeFormat("en-US", { month: "short", year: "numeric", timeZone: "UTC" });

/** The last month a cohort row has data for. Each newer cohort has one month less. */
export const lastCohortMonth = (row: number) => COHORT_MONTHS - 1 - row;

function buildSegment(seed: number, sizes: number[], firstMonth: number, keep: number): Cohort[] {
  const random = seededRandom(seed);
  return sizes.map((size, row) => {
    const retained = [size];
    // Newer cohorts hold a little better, as onboarding improved through the year.
    const first = firstMonth + row * 0.005 + (random() - 0.5) * 0.06;
    for (let month = 1; month <= lastCohortMonth(row); month += 1) {
      const before = retained[month - 1] ?? size;
      const next = month === 1 ? size * first : before * (keep + (random() - 0.5) * 0.03);
      retained.push(Math.min(before, Math.round(next)));
    }
    return { label: MONTH.format(new Date(Date.UTC(2026, 1 + row, 1))), size, retained };
  });
}

const SELF_SERVE = buildSegment(71, [64, 71, 58, 77, 83, 69, 88, 94, 102], 0.76, 0.93);
const SALES_LED = buildSegment(29, [22, 18, 25, 21, 27, 24, 30, 28, 33], 0.9, 0.965);

// Every clinic is in exactly one segment, so the whole is the two segments added cell by cell.
const EVERYONE: Cohort[] = SELF_SERVE.map((cohort, row) => {
  const other = SALES_LED[row];
  return {
    label: cohort.label,
    size: cohort.size + (other?.size ?? 0),
    retained: cohort.retained.map((count, month) => count + (other?.retained[month] ?? 0)),
  };
});

/** The sample cohorts for each segment. The two segments add up to "all" in every cell. */
export const COHORTS = { all: EVERYONE, selfServe: SELF_SERVE, salesLed: SALES_LED } satisfies Record<CohortSegment, Cohort[]>;

/** The percent of a cohort still booking in a month since signup. */
export function cohortPercent(cohort: Cohort, month: number): number {
  return cohort.size === 0 ? 0 : ((cohort.retained[month] ?? 0) / cohort.size) * 100;
}

/** Retention in one month across the cohorts old enough to have reached it. */
export interface RetentionFigure {
  retained: number;
  size: number;
  percent: number;
}

/** Retention in one month across every cohort old enough to have reached it, weighted by cohort size. */
export function retentionAt(cohorts: Cohort[], month: number): RetentionFigure {
  let retained = 0;
  let size = 0;
  for (const cohort of cohorts) {
    const count = cohort.retained[month];
    if (count === undefined) continue;
    retained += count;
    size += cohort.size;
  }
  return { retained, size, percent: size === 0 ? 0 : (retained / size) * 100 };
}

/** The five shade steps, lightest first. The darkest stays light enough for the cell text to read at 4.5 to 1. Each cell also prints its percent, so the shade is never the only cue. */
export const COHORT_SHADES = ["bg-chart-1/6", "bg-chart-1/12", "bg-chart-1/18", "bg-chart-1/26", "bg-chart-1/34"];

/** Where each shade step starts, in the same order as the shades. Numbers only, so the key fits one line. */
export const COHORT_SHADE_LABELS = ["<40%", "40%", "55%", "70%", "85%+"];

/** The shade step, 0 to 4, for a retention percent. */
export function shadeStep(percent: number): number {
  if (percent >= 85) return 4;
  if (percent >= 70) return 3;
  if (percent >= 55) return 2;
  if (percent >= 40) return 1;
  return 0;
}

/**
 * Where an arrow, Home or End key moves the cell cursor. The triangle is
 * ragged, so a move up or down lands on the last month the new cohort has.
 * Returns null for any other key.
 */
export function moveCohortCell(cell: CohortCell, key: string): CohortCell | null {
  const land = (row: number, col: number) => ({ row, col: Math.min(col, lastCohortMonth(row)) });
  switch (key) {
    case "ArrowLeft":
      return land(cell.row, Math.max(0, cell.col - 1));
    case "ArrowRight":
      return land(cell.row, cell.col + 1);
    case "ArrowUp":
      return land(Math.max(0, cell.row - 1), cell.col);
    case "ArrowDown":
      return land(Math.min(COHORT_MONTHS - 1, cell.row + 1), cell.col);
    case "Home":
      return land(cell.row, 0);
    case "End":
      return land(cell.row, COHORT_MONTHS);
    default:
      return null;
  }
}

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

// NumberTicker memoises its formatter on the options object, so every block
// passes one of these constants and never an inline object.

/** A whole number with thousands separators, for a rolling figure. */
export const ROLL_WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

/** A number with one decimal place, for a rolling figure. */
export const ROLL_ONE_PLACE: Intl.NumberFormatOptions = { minimumFractionDigits: 1, maximumFractionDigits: 1 };

/** A dollar amount with no cents, for a rolling figure. */
export const ROLL_MONEY: Intl.NumberFormatOptions = { style: "currency", currency: "USD", maximumFractionDigits: 0 };

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import type { KeyboardEvent, PointerEvent } from "react";

import { cn } from "@/lib/utils";

import {
  COHORT_MONTHS,
  type Cohort,
  type CohortCell,
  cohortPercent,
  lastCohortMonth,
  moveCohortCell,
} from "../../lib/cohort-retention-data";
import { toY } from "../../lib/plot";
import { PointTip } from "../../parts/point-tip";
import type { RetentionViewProps } from "./retention-grid";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

// Critically damped: a curve settles on the new segment with no wobble.
const MORPH: Transition = { type: "spring", stiffness: 260, damping: 32, mass: 1 };
const INSTANT: Transition = { duration: 0 };

const EXTENT: [number, number] = [20, 100];
const TICKS = [100, 80, 60, 40, 20];
const MONTHS = Array.from({ length: COHORT_MONTHS }, (_, month) => month);

const xOf = (month: number) => (month / (COHORT_MONTHS - 1)) * 100;
const clamp = (value: number) => Math.min(1, Math.max(0, value));

function curvePath(cohort: Cohort): string {
  return cohort.retained
    .map((_, month) => `${month === 0 ? "M" : "L"}${xOf(month).toFixed(2)} ${toY(cohortPercent(cohort, month), EXTENT).toFixed(2)}`)
    .join(" ");
}

/**
 * The same triangle as one curve per signup month. The plot is a single tab
 * stop: up and down pick a cohort, left and right pick a month, Home and End
 * jump along the curve, and Escape clears the readout. The inspected point
 * gets a ring, a line down its month and a card with its figures.
 */
export function RetentionCurves({ label, cohorts, cursor, inspected, details, onCursor, onActive, onHover }: RetentionViewProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : MORPH;

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") {
      onActive(false);
      return;
    }
    const next = moveCohortCell(cursor, event.key);
    if (!next) return;
    event.preventDefault();
    onCursor(next);
    onActive(true);
  };

  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const box = event.currentTarget.getBoundingClientRect();
    if (box.width === 0 || box.height === 0) return;
    const col = Math.round(clamp((event.clientX - box.left) / box.width) * (COHORT_MONTHS - 1));
    const percent = EXTENT[1] - clamp((event.clientY - box.top) / box.height) * (EXTENT[1] - EXTENT[0]);
    let nearest: CohortCell | null = null;
    let gap = Number.POSITIVE_INFINITY;
    for (let row = 0; row < cohorts.length; row += 1) {
      const cohort = cohorts[row];
      if (!cohort || col > lastCohortMonth(row)) continue;
      const distance = Math.abs(cohortPercent(cohort, col) - percent);
      if (distance < gap) {
        gap = distance;
        nearest = { row, col };
      }
    }
    onHover(nearest);
  };

  const marked = inspected ? cohorts[inspected.row] : undefined;
  const point = inspected && marked ? { x: xOf(inspected.col), y: toY(cohortPercent(marked, inspected.col), EXTENT) } : null;

  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div aria-hidden="true" className="mb-11 flex w-9 shrink-0 flex-col justify-between text-right text-xs tabular-nums text-muted-foreground">
        {TICKS.map((tick) => (
          <span key={tick} className="-my-2 leading-4">
            {tick}%
          </span>
        ))}
      </div>
      <div className="flex min-w-0 flex-1 flex-col">
        <div
          role="application"
          aria-roledescription="chart"
          aria-label={`${label}. Each line is one signup month. Up and down choose a signup month, left and right choose a month since signup.`}
          tabIndex={0}
          onKeyDown={onKeyDown}
          onFocus={() => onActive(true)}
          onBlur={() => onActive(false)}
          onPointerDown={onPointerMove}
          onPointerMove={onPointerMove}
          // A finger leaves when it lifts, so only a mouse clears the point on the way out.
          onPointerLeave={(event) => {
            if (event.pointerType === "mouse") onHover(null);
          }}
          className="relative min-h-80 flex-1 cursor-crosshair touch-pan-y rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-4 focus-visible:ring-offset-card"
        >
          <div aria-hidden="true" className="absolute inset-0 flex flex-col justify-between">
            {TICKS.map((tick) => (
              <span key={tick} className="h-px w-full bg-border/60" />
            ))}
          </div>
          <svg aria-hidden="true" viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 size-full overflow-visible">
            {cohorts.map((cohort, row) => {
              const chosen = inspected?.row === row;
              return (
                <motion.path
                  key={cohort.label}
                  initial={false}
                  animate={{ d: curvePath(cohort) }}
                  transition={transition}
                  fill="none"
                  strokeWidth={chosen ? 2.5 : 1.25}
                  strokeLinejoin="round"
                  vectorEffect="non-scaling-stroke"
                  className={cn(chosen ? "stroke-chart-1" : inspected ? "stroke-muted-foreground/35" : "stroke-muted-foreground/70")}
                />
              );
            })}
          </svg>
          {inspected && point ? (
            <>
              <div aria-hidden="true" className="left-(--x) pointer-events-none absolute inset-y-0" style={
                // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                { "--x": `${point.x}%` } as VarStyle
              }>
                <span className="absolute inset-y-0 -left-px w-px bg-foreground/30" />
                <span
                  className="top-(--y) absolute -left-2 size-4 -translate-y-1/2 rounded-full border-2 border-chart-1 bg-card shadow-sm"
                  style={
                    // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                    { "--y": `${point.y}%` } as VarStyle
                  }
                />
              </div>
              <PointTip x={point.x} y={point.y} {...details(inspected)} />
            </>
          ) : null}
        </div>
        <div aria-hidden="true" className="mt-2 flex justify-between text-xs tabular-nums text-muted-foreground">
          {MONTHS.map((month) => (
            <span key={month}>{month}</span>
          ))}
        </div>
        <p className="mt-1 text-xs text-muted-foreground">Months since signup</p>
      </div>
    </div>
  );
}

import { cn } from "@/lib/utils";

import type { VarStyle } from "@/components/blocks/lib/css-vars";
import { RollingText } from "./rolling-text";

/** One line of a point's details. */
export interface PointTipRow {
  label: string;
  value: string;
  /** A class that colours the row's marker, such as `bg-chart-1`. Omit for a row with no series. */
  marker?: string;
  /** Draws the marker as a dashed line, for an earlier period. */
  dashed?: boolean;
}

/** Props for the card that shows one point's details. */
export interface PointTipProps {
  /** Where the point sits in its plot, from 0 to 100 on each axis, measured from the top left. */
  x: number;
  y: number;
  title: string;
  rows: PointTipRow[];
  /** A closing line, such as the difference between two rows. */
  note?: string;
  className?: string;
}

/**
 * A small card beside an inspected point. It sits on the side of the point
 * with more room and stays inside the plot. In a plot narrower than the card
 * and the point together, it may cover the point rather than be cut off.
 * The digits of each value roll to the next point's figure as the point changes.
 * The card blurs what is behind it, so a design system with a see-through popover stays legible.
 * It is decorative for screen readers: the plot's live readout says the same.
 */
export function PointTip({ x, y, title, rows, note, className }: PointTipProps) {
  const onLeft = x > 55;
  return (
    <div
      aria-hidden="true"
      className={cn("pointer-events-none absolute top-(--y) z-10", onLeft ? "right-(--side)" : "left-(--side)", className)}
      style={
        // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
        {
          // The card hangs one rem from the point, but never past the plot's edge: 14rem is its widest.
          "--side": `min(calc(${onLeft ? 100 - x : x}% + 1rem), calc(100% - 14rem))`,
          "--y": `${Math.min(78, Math.max(22, y))}%`,
        } as VarStyle
      }
    >
      <div
        className={cn(
          "flex w-max max-w-56 -translate-y-1/2 flex-col gap-1.5 rounded-xl border border-border bg-popover px-3 py-2 text-popover-foreground shadow-lg backdrop-blur-md",
        )}
      >
        <span className="text-xs text-muted-foreground">{title}</span>
        {rows.map((row) => (
          <span key={row.label} className="flex items-center justify-between gap-6 text-sm">
            <span className="flex items-center gap-2 text-muted-foreground">
              {row.marker ? (
                <span className={cn("h-0.5 w-3 rounded-full", row.dashed ? "border-t border-dashed border-current" : row.marker)} />
              ) : null}
              {row.label}
            </span>
            <RollingText text={row.value} className="font-medium" />
          </span>
        ))}
        {note ? <span className="border-t border-border pt-1.5 text-xs text-muted-foreground">{note}</span> : null}
      </div>
    </div>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

"use client";

import { type KeyboardEvent, useRef, useState } from "react";

import { cn } from "@/lib/utils";
import { Table } from "@/components/ui/table";

import {
  COHORT_MONTHS,
  COHORT_SHADES,
  type Cohort,
  type CohortCell,
  cohortPercent,
  lastCohortMonth,
  moveCohortCell,
  shadeStep,
} from "../../lib/cohort-retention-data";
import { formatWhole } from "../../lib/format";
import { PointTip, type PointTipProps } from "../../parts/point-tip";

/** Props shared by the two retention views, so one cursor drives both. */
export interface RetentionViewProps {
  /** Names the view for screen readers. */
  label: string;
  cohorts: Cohort[];
  /** The cell that holds the tab stop. */
  cursor: CohortCell;
  /** The cell the readout describes, or null when nothing is inspected. */
  inspected: CohortCell | null;
  /** The details shown in the card beside the inspected cell. */
  details: (cell: CohortCell) => Pick<PointTipProps, "title" | "rows" | "note">;
  onCursor: (cell: CohortCell) => void;
  /** Called with true when the keyboard starts inspecting, and false on Escape or blur. */
  onActive: (active: boolean) => void;
  onHover: (cell: CohortCell | null) => void;
}

const MONTHS = Array.from({ length: COHORT_MONTHS }, (_, month) => month);

/** Where a cell sits in the frame around the scrolling table, from 0 to 100 on each axis. */
interface CellAnchor {
  key: string;
  x: number;
  y: number;
}

const cellKey = (cell: CohortCell) => `${cell.row}-${cell.col}`;
const clampPercent = (value: number) => Math.min(100, Math.max(0, value));

/**
 * The edge of a cell the card hangs from: the right edge, or the left edge
 * once the cell passes the middle, so the card never covers the cell's figure.
 */
function anchorFor(key: string, cell: HTMLElement, frame: HTMLElement): CellAnchor | null {
  const box = frame.getBoundingClientRect();
  const at = cell.getBoundingClientRect();
  if (box.width === 0 || box.height === 0) return null;
  const left = ((at.left - box.left) / box.width) * 100;
  const right = ((at.right - box.left) / box.width) * 100;
  // The card flips to the left of any point past 55, so each side stays on its own half.
  const x = (left + right) / 2 > 55 ? Math.max(left, 55.5) : Math.min(right, 55);
  return { key, x: clampPercent(x), y: clampPercent(((at.top + at.height / 2 - box.top) / box.height) * 100) };
}

/**
 * The retention triangle as a grid. One cell holds the tab stop; arrows move
 * it, Home and End jump within a cohort, and Escape clears the readout. The
 * card for the inspected cell sits outside the scrolling table, so the table
 * never clips it.
 */
export function RetentionGrid({ label, cohorts, cursor, inspected, details, onCursor, onActive, onHover }: RetentionViewProps) {
  const cells = useRef(new Map<string, HTMLTableCellElement>());
  const frame = useRef<HTMLDivElement>(null);
  // One anchor for the pointer and one for the focus, so the card returns to the focused cell when the pointer leaves.
  const [hoverAnchor, setHoverAnchor] = useState<CellAnchor | null>(null);
  const [focusAnchor, setFocusAnchor] = useState<CellAnchor | null>(null);
  const inspectedKey = inspected ? cellKey(inspected) : null;
  const anchor = [hoverAnchor, focusAnchor].find((item) => item !== null && item.key === inspectedKey) ?? null;

  const measure = (key: string, cell: HTMLElement) => (frame.current ? anchorFor(key, cell, frame.current) : null);
  const measureKey = (key: string) => {
    const cell = cells.current.get(key);
    return cell ? measure(key, cell) : null;
  };

  const onKeyDown = (event: KeyboardEvent<HTMLTableElement>) => {
    if (event.key === "Escape") {
      onActive(false);
      return;
    }
    const next = moveCohortCell(cursor, event.key);
    if (!next) return;
    event.preventDefault();
    onCursor(next);
    onActive(true);
    cells.current.get(`${next.row}-${next.col}`)?.focus();
  };

  return (
    <div ref={frame} className="relative min-w-0">
      {/* The table's own frame scrolls; a scroll event does not bubble, so the capture phase hears it here. */}
      <div
        className="min-w-0 p-1"
        onScrollCapture={() => {
          // A scrolled table moves every cell, so measure the anchored cells again.
          setHoverAnchor((current) => (current ? measureKey(current.key) : null));
          setFocusAnchor((current) => (current ? measureKey(current.key) : null));
        }}
      >
      <Table
        role="grid"
        aria-label={`${label}. Use the arrow keys to move between cells.`}
        onKeyDown={onKeyDown}
        onPointerLeave={() => onHover(null)}
        className="min-w-xl"
      >
        <thead>
          <tr className="text-xs text-muted-foreground tabular-nums">
            <th scope="col" className="pb-1 pl-1 text-left font-medium">
              Signed up
            </th>
            <th scope="col" className="px-2 pb-1 text-right font-medium">
              Clinics
            </th>
            {MONTHS.map((month) => (
              <th key={month} scope="col" className="pb-1 font-medium">
                <span className="sr-only">Month </span>
                {month}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {cohorts.map((cohort, row) => (
            <tr key={cohort.label} className="text-xs tabular-nums">
              <th scope="row" className="pl-1 text-left font-medium whitespace-nowrap text-foreground">
                {cohort.label}
              </th>
              <td className="px-2 text-right text-muted-foreground">{formatWhole(cohort.size)}</td>
              {MONTHS.map((col) => {
                if (col > lastCohortMonth(row)) {
                  return (
                    <td key={col} role="gridcell">
                      <span className="sr-only">Not reached yet</span>
                    </td>
                  );
                }
                const percent = cohortPercent(cohort, col);
                const isCursor = cursor.row === row && cursor.col === col;
                const isInspected = inspected?.row === row && inspected.col === col;
                return (
                  <td
                    key={col}
                    role="gridcell"
                    ref={(node) => {
                      if (node) cells.current.set(`${row}-${col}`, node);
                      else cells.current.delete(`${row}-${col}`);
                    }}
                    tabIndex={isCursor ? 0 : -1}
                    onFocus={(event) => {
                      onCursor({ row, col });
                      onActive(true);
                      setFocusAnchor(measure(`${row}-${col}`, event.currentTarget));
                    }}
                    onBlur={() => onActive(false)}
                    onPointerEnter={(event) => {
                      onHover({ row, col });
                      setHoverAnchor(measure(`${row}-${col}`, event.currentTarget));
                    }}
                    className={cn(
                      "h-11 min-w-9 cursor-default rounded-sm p-px text-center text-foreground outline-none sm:h-9",
                      "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset",
                      isInspected ? "ring-2 ring-foreground ring-inset" : undefined,
                    )}
                  >
                    {/* The shade sits inside the cell, so the cells keep a gap without spacing on the table. */}
                    <span
                      className={cn(
                        "flex h-10 items-center justify-center rounded-sm motion-safe:transition-colors motion-safe:duration-200 sm:h-8",
                        COHORT_SHADES[shadeStep(percent)],
                      )}
                    >
                      {Math.round(percent)}%
                    </span>
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </Table>
      </div>
      {inspected && anchor ? <PointTip x={anchor.x} y={anchor.y} {...details(inspected)} /> : null}
    </div>
  );
}
